  `editedbyname` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `editedbynamear` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `omitted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
